export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves the ball's overlap with the bricks at its CURRENT position: every
// overlapping brick is broken and scored, and the ball is deflected. Pure
// logic (no DOM), so the whole brick-collision path is unit-testable.
// Returns the number of bricks broken.
export function collideBricks(state) {
  const { ball } = state;
  let broken = 0;
  for (const brick of state.bricks) {
    if (!brick.alive || !collides(ball, brick)) continue;
    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
    broken += 1;
    ball.vy = -ball.vy;
  }
  return broken;
}

