test('seam (side-by-side): one pass through two bricks produces a single bounce', () => {
  const state = createState(1);
  const left = state.bricks.find((b) => b.row === 0 && b.col === 0);
  const right = state.bricks.find((b) => b.row === 0 && b.col === 1);
  // Ball (diam 14) over the 80 px-pitch seam, overlapping both bricks, going down.
  state.ball = { x: left.x + left.w + 3, y: left.y - 5, r: BALL_R, vx: 0, vy: 200 };
  collideBricks(state);
  assert.equal(left.alive, false);
  assert.equal(right.alive, false);
  assert.equal(
    Math.sign(state.ball.vy),
    UP,
    'exactly one vy flip: two cancelling flips would let the ball through',
  );
});

test('seam (stacked rows): one pass through two bricks produces a single bounce', () => {
  const state = createState(1);
  const top = state.bricks.find((b) => b.row === 0 && b.col === 0);
  const below = state.bricks.find((b) => b.row === 1 && b.col === 0);
  // Ball (diam 14) squeezed in the 8 px gap between rows 0 and 1: overlaps both.
  state.ball = { x: top.x + top.w / 2, y: top.y + top.h + BRICK_GAP / 2, r: BALL_R, vx: 0, vy: 200 };
  collideBricks(state);
  assert.equal(top.alive, false);
  assert.equal(below.alive, false);
  assert.equal(Math.sign(state.ball.vy), UP, 'a single flip, not two cancelling ones');
});

