test('step: a fast ball bounces off the first brick it meets (no tunneling)', () => {
  // Trigger computed from the constants: at level 6 the max step is
  // ballSpeed(6) * 0.05 = 35.5 px, which exceeds BRICK_H + 2*BALL_R = 34 px
  // (level 5 caps at 31 px < 34 px). A single-position check would skip the
  // top brick and hit the row below instead; the sub-stepped step() must hit
  // the first brick.
  const state = createState(6);
  const top = state.bricks.find((b) => b.row === 0 && b.x < 100);
  const below = state.bricks.find((b) => b.row === 1 && b.x === top.x);
  state.ball = { x: top.x + top.w / 2, y: top.y - BALL_R - 1, r: BALL_R, vx: 0, vy: ballSpeed(6) };
  step(state, 0.05); // the capped dt: worst-case per-frame travel
  assert.equal(top.alive, false, 'the first brick in the path is hit and broken');
  assert.equal(below.alive, true, 'the ball never reaches the second row');
  assert.equal(Math.sign(state.ball.vy), UP, 'the ball bounced, it did not pass through');
});

