const STORAGE_KEY = 'neon.best';

// Sub-step budget for step(): no single sub-step travels further than this.
// The thinnest obstacles the ball must not leap over are a brick face
// (BRICK_H + 2*BALL_R = 34 px) and the paddle band (PADDLE_H + 2*BALL_R =
// 26 px); 8 px keeps every collision detectable at any speed, dt included.
const MAX_MOVE = 8;

export function step(state, dt) {
  const { ball, paddle } = state;

  // Sub-step the move: one frame at the capped dt (50 ms) travels up to
  // ballSpeed(level) * 0.05 px — at level 6 that is 35.5 px, more than a
  // brick face (34 px). Checking the end position only would let the ball
  // leap over a brick; bounding each sub-step below the thinnest obstacle
  // guarantees every obstacle on the path is actually hit.
  const dx = ball.vx * dt;
  const dy = ball.vy * dt;
  const subSteps = Math.max(1, Math.ceil(Math.max(Math.abs(dx), Math.abs(dy)) / MAX_MOVE));

  for (let i = 0; i < subSteps; i++) {
    ball.x += dx / subSteps;
    ball.y += dy / subSteps;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
